Tool response:
Tool: create_building
Description: Create Building
Parameters:
    {
      "type": "object",
      "properties": {
        "portfolio_id": {
          "type": "integer",
          "title": "Portfolio Id"
        },
        "name": {
          "type": "string",
          "title": "Name"
        },
        "address_line1": {
          "type": "string",
          "title": "Address Line1"
        },
        "address_line2": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Address Line2"
        },
        "city": {
          "type": "string",
          "title": "City"
        },
        "state": {
          "type": "string",
          "title": "State"
        },
        "postal_code": {
          "type": "string",
          "title": "Postal Code"
        }
      },
      "required": [
        "portfolio_id",
        "name",
        "address_line1",
        "city",
        "state",
        "postal_code"
      ]
    }

Tool response:
Tool: create_units
Description: Create Units
Parameters:
    {
      "type": "object",
      "properties": {
        "building_id": {
          "type": "integer",
          "title": "Building Id"
        },
        "units": {
          "items": {
            "properties": {
              "unit_number": {
                "type": "string",
                "title": "Unit Number"
              },
              "bedrooms": {
                "type": "integer",
                "title": "Bedrooms"
              },
              "bathrooms": {
                "type": "number",
                "title": "Bathrooms"
              },
              "square_feet": {
                "type": "integer",
                "title": "Square Feet"
              },
              "monthly_rent": {
                "type": "number",
                "title": "Monthly Rent"
              },
              "availability_status": {
                "type": "string",
                "title": "Availability Status"
              }
            },
            "type": "object",
            "required": [
              "unit_number",
              "bedrooms",
              "bathrooms",
              "square_feet",
              "monthly_rent",
              "availability_status"
            ],
            "title": "UnitItem"
          },
          "type": "array",
          "title": "Units"
        }
      },
      "required": [
        "building_id",
        "units"
      ]
    }
